'use client'

import * as React from 'react'
import { IconRotateClockwise } from '@tabler/icons-react'
import { HandleReel } from '@/components/spaceui/handle-reel'

const PREFIX_OPTIONS = ['ryna.me/', '@', 'space.id/']

export default function Demo() {
  const [prefix, setPrefix] = React.useState(PREFIX_OPTIONS[0])
  const [trigger, setTrigger] = React.useState(0)

  return (
    <div className="flex min-h-[460px] w-full flex-col items-center justify-center gap-8 p-6 bg-background text-foreground">
      {/* Interactive Controls Bar */}
      <div className="flex flex-wrap items-center justify-center gap-3">
        <div className="flex items-center gap-1 rounded-2xl border border-border/60 bg-muted/40 p-1 backdrop-blur-md">
          {PREFIX_OPTIONS.map((opt) => (
            <button
              key={opt}
              type="button"
              onClick={() => {
                setPrefix(opt)
                setTrigger((t) => t + 1)
              }}
              className={`rounded-xl px-3 py-1 text-xs font-semibold transition-all cursor-pointer ${
                prefix === opt
                  ? 'bg-primary text-primary-foreground shadow-xs'
                  : 'text-muted-foreground hover:text-foreground hover:bg-muted/70'
              }`}
            >
              {opt}
            </button>
          ))}
        </div>

        <button
          type="button"
          onClick={() => setTrigger((t) => t + 1)}
          className="flex items-center gap-1.5 rounded-2xl border border-border/60 bg-muted/70 px-3.5 py-1.5 text-xs font-semibold text-foreground/80 shadow-xs transition-all hover:bg-muted hover:text-foreground hover:scale-105 active:scale-95 cursor-pointer"
        >
          <IconRotateClockwise className="size-3.5" />
          <span>Spin again</span>
        </button>
      </div>

      <HandleReel
        prefix={prefix}
        finalName="ryna"
        trigger={trigger}
        loop={false}
      />
    </div>
  )
}
